import{_ as a,C as n,o as s,c as r,aj as e,G as i}from"./chunks/framework.BwH0p-pt.js";const g=JSON.parse('{"title":"Notifications","description":"","frontmatter":{},"headers":[],"relativePath":"2.0/notifications/index.md","filePath":"2.0/notifications/index.md","lastUpdated":1785836850000}'),l={name:"2.0/notifications/index.md"};function c(p,t,d,u,m,h){const o=n("ImagePopup");return s(),r("div",null,[t[0]||(t[0]=e('<h1 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h1><p>Notifications in <a href="https://unopim.com/" target="_blank" rel="noreferrer">UnoPim</a> provide a real-time, in-app alerting system that keeps administrators informed about important events and background processes. Introduced in <strong>v0.2.0</strong>, the notification system works alongside optional email notifications to ensure you never miss critical updates.</p><p>Whether it&#39;s the completion of a bulk import, a failed export job, or a product change, notifications help you stay on top of everything happening in your PIM without needing to constantly check each section manually.</p><h3 id="accessing-notifications" tabindex="-1">Accessing Notifications <a class="header-anchor" href="#accessing-notifications" aria-label="Permalink to &quot;Accessing Notifications&quot;">​</a></h3><p>To access your notifications, click the <strong>Bell Icon</strong> in the top navigation bar of the Admin panel. This opens the notification panel where you can view all recent alerts.</p>',5)),i(o,{src:"/assets/2.0/images/notifications/notification-panel.png",alt:"Notification Panel"}),t[1]||(t[1]=e('<h3 id="types-of-notifications" tabindex="-1">Types of Notifications <a class="header-anchor" href="#types-of-notifications" aria-label="Permalink to &quot;Types of Notifications&quot;">​</a></h3><p>UnoPim sends notifications for various system events. Below are the main categories:</p><p><strong>1) Import/Export Job Status Updates</strong></p><p>Whenever you run a bulk import or export job, UnoPim automatically sends a notification when the job is completed, failed, or requires attention. This allows you to monitor long-running data transfer operations without staying on the job tracker page.</p><ul><li><strong>Completed</strong> — The import or export job finished successfully.</li><li><strong>Failed</strong> — The job encountered errors and could not complete.</li><li><strong>Completed with Errors</strong> — The job finished but some records were skipped due to validation issues.</li></ul><p><strong>2) Product Changes</strong></p><p>Notifications can alert you when significant product data modifications occur, such as bulk updates or changes made through the API. This is useful when multiple team members are working on the product catalog simultaneously.</p><p><strong>3) System Notifications</strong></p><p>General system-level alerts, such as scheduled maintenance reminders or important configuration changes, are also delivered through the notification panel.</p><h3 id="notification-panel-features" tabindex="-1">Notification Panel Features <a class="header-anchor" href="#notification-panel-features" aria-label="Permalink to &quot;Notification Panel Features&quot;">​</a></h3><p>Click the <strong>bell icon</strong> in the top-right of the header to open the panel. A <strong>green dot</strong> on the bell indicates unread notifications.</p>',11)),i(o,{src:"/assets/2.0/images/notifications/notification-panel.png",alt:"Notifications panel"}),t[2]||(t[2]=e('<p>The panel lists recent notifications. Each entry shows:</p><ul><li><strong>Title</strong> — job type + sequential number, e.g., <code>Import #15</code>, <code>Export #1</code>. The number matches the <strong>ID</strong> column in the <a href="./../data-transfer/job-tracker.html">Job Tracker</a>, so you can click through and find the exact run.</li><li><strong>Body</strong> — the profile code + terminal state, e.g., <em>&quot;Import &#39;Test&#39; completed&quot;</em> — useful for telling apart multiple runs of the same profile.</li><li><strong>Relative timestamp</strong> — e.g., <em>&quot;4 days ago&quot;</em>.</li></ul><p>Two actions sit at the bottom of the panel:</p><ul><li><strong>View All</strong> — opens the full notifications page, where you can browse, filter, and manage individual entries.</li><li><strong>Mark as Read</strong> — a single bulk action that clears the unread state for every notification visible in the panel.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Per-notification <em>Mark as Read / Unread</em> and <em>Clear Notifications</em> controls now live on the full notifications page (via <strong>View All</strong>). The panel itself keeps only the bulk <em>Mark as Read</em> and <em>View All</em> actions so it stays scannable.</p></div><h3 id="email-notifications" tabindex="-1">Email Notifications <a class="header-anchor" href="#email-notifications" aria-label="Permalink to &quot;Email Notifications&quot;">​</a></h3><p>In addition to in-app notifications, UnoPim supports email notifications for critical events. When enabled, the system sends an email to the administrator&#39;s registered email address alongside the in-app notification.</p><p><strong>How Email Notifications Work</strong></p><p>Email notifications are sent automatically for key events such as import/export job completions and failures. This ensures that even if you are not actively logged into the Admin panel, you still receive timely updates.</p><p><strong>Configuration</strong></p><p>Email delivery is configured at the infrastructure level via your UnoPim <code>.env</code> file — set <code>MAIL_MAILER</code>, <code>MAIL_HOST</code>, <code>MAIL_USERNAME</code>, <code>MAIL_PASSWORD</code>, and <code>MAIL_FROM_ADDRESS</code> to match your mail provider (SMTP, Mailgun, Postmark, etc.). UnoPim uses standard Laravel mail drivers and picks up the settings automatically on application boot.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Test your mail configuration end-to-end before relying on notification emails. Trigger a low-stakes event (e.g., a small import) and confirm the email arrives; if it doesn&#39;t, check your Laravel log (<code>storage/logs/laravel.log</code>) for mailer errors.</p></div><p>By using both in-app and email notifications together, you can ensure complete visibility into all important events happening within your UnoPim instance.</p>',13))])}const y=a(l,[["render",c]]);export{g as __pageData,y as default};
